@startuml

class AlphaInsurance {
  + companyName : string
}

class Customer {
  + customerId : int
  + name : string
  + address : string
}

class Broker {
  + brokerId : int
  + name : string
}

class HelpDesk {}

class Contract {
  + contractId : int
  + signingDate : date
  + billingFrequency : string
  + price : float
}

abstract class InsurancePolicy {
  + policyType : string
}

class PreliminaryOffer {
  + offerId : int
  + expiryDate : date
}

class ClaimCase {
  + caseId : int
  + status : string
  + description : string
}

class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : int
  + findings : string
  + issueDate : date
}

class CompensationDecision {
  + decisionId : int
  + eligibleCosts : float
  + isApproved : boolean
}

class Payment {
  + paymentId : int
  + amount : float
  + paymentDate : date
}

InsurancePolicy --|> Policy
PreliminaryOffer --|> InsurancePolicy

AlphaInsurance "1" *-- "*" Customer
Broker "1" -- "*" Customer
Customer "1" -- "*" Contract
Contract "1" -- "1" InsurancePolicy
PreliminaryOffer "0..1" -- "0..1" Customer
PreliminaryOffer "0..1" -- "0..1" Contract
Contract "1" -- "1..*" ClaimCase
ClaimCase "1" -- "1..*" EstimatorReport
Estimator "1" -- "*" EstimatorReport
ClaimCase "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" Payment
Payment "*" -- "1" Customer
HelpDesk ..> Contract : traces
@enduml

